import optax
# Use the verified gated implementation path to avoid import issues
from storage.noema.submissions.dual_path_hybrid_motif_heads_gated import build_network

BASE_SEED = 7
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        'hidden_dim': 256,
        'd_model': 256,
        'kernel_size': 7,
        'dropout_rate': 0.10,
        'motif_kernel_size': 5,
        'aggregator': 'mean_max',
        'head_dropout': 0.05,
        'learning_rate': 0.001,
        'grad_clip': 1.0,
        'fusion': 'scalar_gate'
    }

def create_network(hparams):
    return build_network(hparams.get('d_output', 1), hparams.get('task_type', 'regression'), hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.01)
    )

def complete(params, opt_state, trial_data):
    ds, vm = trial_data.get('dataset'), trial_data.get('val_metric')
    print(f"[Complete] {ds} val_metric={vm}")
